{"cards": [{"node_code": "N_59298c64c5e32ed1", "definition": "研究铁路车站、车辆、线路及作业场所的火灾预防、消防管理、灭火技术及应急疏散策略，旨在降低火灾风险并保障人员与财产安全的管理领域。", "boundary": "本节点聚焦于铁路系统内的“防火”与“消防”管理。边界在于区分“管理策略”与“纯消防工程技术”：本节点侧重铁路特定场景下的消防制度、隐患排查、灭火组织及疏散预案；若涉及通用消防设备（如灭火器、喷淋系统）的机械原理或材料科学，归入消防工程或相关技术节点。与行车安全区分在于，防火安全关注的是火灾这一特定灾害源，而非列车运行冲突。", "includes": ["铁路站场、车辆及仓库的火灾风险评估与隐患排查", "铁路消防管理制度、灭火救援组织及应急疏散预案", "铁路特定环境下的防火规范与消防安全教育"], "excludes": ["通用消防设备的设计、制造及材料科学原理", "非铁路领域的通用消防工程技术", "与火灾无关的行车冲突或设备故障安全"], "sibling_distinctions": [{"other_code": "N_a42a33255e605e9b", "rule": "区分依据为灾害类型：行车安全侧重列车运行中的冲突、脱轨等动态风险；防火安全侧重火灾这一特定静态/动态灾害的预防与控制。"}, {"other_code": "N_9340b9566b38e476", "rule": "区分依据为阶段：防火安全侧重事前预防与事中控制；事故分析及处理侧重事后调查、原因分析及责任认定。"}], "cross_boundary_rule": "若内容涉及“铁路火灾事故调查”，若侧重火灾原因的技术鉴定归入事故分析及处理；若侧重火灾发生时的灭火指挥与疏散管理归入本节点。"}, {"node_code": "N_9340b9566b38e476", "definition": "研究铁路交通事故的调查程序、原因分析方法、责任认定机制及后续整改措施，旨在通过事故复盘提升系统安全水平的管理领域。", "boundary": "本节点聚焦于“事故后”的分析与处理。边界在于区分“事故分析”与“事故预防”：本节点侧重对已发生事故的法医式调查、数据复盘及制度漏洞挖掘；预防性风险评估归入行车安全或防火安全等具体领域。若涉及事故现场的紧急救援行动，归入救援工作；若涉及事故的法律诉讼或赔偿，归入法律节点。", "includes": ["铁路交通事故调查程序、证据收集与原因分析技术", "事故责任认定标准、安全整改建议及案例库建设", "事故统计分析与安全趋势预测"], "excludes": ["事故现场的紧急救援与抢修作业", "事故相关的法律诉讼、赔偿谈判及司法程序", "未发生事故时的常规安全风险评估"], "sibling_distinctions": [{"other_code": "N_76024ea512721c99", "rule": "区分依据为时间阶段：救援工作侧重事故发生后的即时响应、人员救助与现场恢复；事故分析及处理侧重事后的系统性调查、原因剖析与制度改进。"}, {"other_code": "N_a42a33255e605e9b", "rule": "区分依据为功能：行车安全侧重运行过程中的实时监控与预防；事故分析及处理侧重对已发生事件的复盘与学习。"}], "cross_boundary_rule": "若内容涉及“事故应急演练”，若侧重演练后的评估与改进归入本节点；若侧重演练过程中的指挥调度与救援操作归入救援工作。"}, {"node_code": "N_76024ea512721c99", "definition": "研究铁路交通事故或灾害发生后的紧急救援组织、救援列车配置、现场抢修技术及人员疏散策略，旨在快速恢复运输秩序并减少损失的管理领域。", "boundary": "本节点聚焦于“应急响应”与“现场处置”。边界在于区分“救援管理”与“救援设备技术”：本节点侧重救援力量的调度、救援流程优化及现场指挥；若涉及救援机车、起重机等具体设备的机械原理，归入车辆或机械工程。与事故分析区分在于，本节点关注“当下”的处置效率，而非“事后”的原因追溯。", "includes": ["铁路救援列车、救援基地的配置与调度管理", "事故现场紧急抢修、人员救助及运输秩序恢复组织", "铁路应急救援预案、演练及多部门协同机制"], "excludes": ["救援专用车辆、机械的设计、制造与维护技术", "事故原因的技术鉴定与责任认定", "非紧急状态下的常规线路维护与施工"], "sibling_distinctions": [{"other_code": "N_9340b9566b38e476", "rule": "区分依据为时间焦点：救援工作侧重事故发生后的即时响应与现场恢复；事故分析及处理侧重事后的系统性调查与制度改进。"}, {"other_code": "N_59298c64c5e32ed1", "rule": "区分依据为灾害类型：救援工作涵盖各类事故（脱轨、火灾、自然灾害等）的综合救援；防火安全侧重火灾这一特定灾害的预防与初期控制。"}], "cross_boundary_rule": "若内容涉及“救援装备”，若侧重装备的调度使用与管理归入本节点；若侧重装备的结构设计或性能参数归入相关工程技术节点。"}]}
